const{createApp,computed,ref,watch,onMounted,onUnmounted}=Vue;const{safeRead,safeWrite,itemSlug,kpUrl,imdbUrl,formatRating,hasRating,isHighRating,langFrom,themeFrom,toggleThemeClass,scrollToTop,installErrorHandler,}=window.ITMoviesCommon;let currentLang="ru";function relatedItems(catalog,item,limit=6){const gs=new Set(item.genres);const isDoc=item.type==="documentary";const scored=catalog.filter((o)=>o!==item&&(isDoc||o.type!=="documentary")).map((o)=>({item:o,overlap:o.genres.filter((g)=>gs.has(g)).length})).sort((a,b)=>b.overlap-a.overlap);const top=scored.filter((s)=>s.overlap>0).map((s)=>s.item);const rest=scored.filter((s)=>s.overlap===0).map((s)=>s.item);return[...top,...rest].slice(0,Math.max(limit,1));}function pickRandom(arr,n){const copy=arr.slice();for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));const tmp=copy[i];copy[i]=copy[j];copy[j]=tmp;}return copy.slice(0,n);}const FILM_TEMPLATE=`
  <header class="top">
    <div class="brand">
      <div class="logo">
        <a href="../../"><img src="../../static/logo.webp" alt="IT Movies" fetchpriority="high" decoding="async" width="100" height="100"></a>
      </div>
      <div class="brand-text">
        <h1 class="film-header-title">{{ title }}</h1>
        <p class="film-header-alt">{{ altTitle }}</p>
        <p class="film-type">{{ typeLabel }}</p>
      </div>
    </div>
    <div class="toolbar">
      <div class="tool-buttons">
        <button type="button" class="theme-toggle" :aria-label="theme === 'dark' ? t.themeToLight : t.themeToDark" :title="theme === 'dark' ? t.themeToLight : t.themeToDark" @click="setTheme(theme === 'dark' ? 'light' : 'dark')">
          <svg v-if="theme === 'dark'" class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.4 15.6A8.5 8.5 0 0 1 8.4 3.6 8.5 8.5 0 1 0 20.4 15.6Z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
          <svg v-else class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3.5" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>
        </button>
        <button type="button" class="lang" :aria-label="t.swapLang + ': ' + (lang === 'ru' ? 'RU' : 'EN')" :title="t.swapLang" @click="setLang(lang === 'ru' ? 'en' : 'ru')">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M3 12h18M12 3c2.4 2.5 3.5 5.5 3.5 9S14.4 18.5 12 21c-2.4-2.5-3.5-5.5-3.5-9S9.6 5.5 12 3Z" fill="none" stroke="currentColor" stroke-width="1.8"/></svg>
          <span>{{ lang === 'ru' ? 'RU' : 'EN' }}</span>
        </button>
      </div>
    </div>
  </header>

  <main>
    <nav class="breadcrumb" :aria-label="t.home">
      <a href="../../">{{ t.home }}</a><span class="bc-sep"> › </span><span class="bc-current"><span class="bc-type">{{ typeLabel }}</span><span class="visually-hidden"> — {{ title }}</span></span>
    </nav>
    <article class="film-main">
      <figure class="film-poster" v-if="posterSrc">
        <img :src="posterSrc" :srcset="posterSrcset" sizes="(max-width: 720px) 92vw, 300px" :alt="title" :width="posterW" :height="posterH" loading="eager" fetchpriority="high" decoding="async">
      </figure>
      <div class="film-info">
        <div class="film-meta">
          <span class="film-meta-item">{{ year }}</span>
          <span class="film-meta-item">{{ genreLabel }}</span>
        </div>
        <p class="film-desc">{{ desc }}</p>
        <div class="ratings">
          <a class="kp" :href="kpHref" target="_blank" rel="noopener noreferrer" :aria-label="t.kp + ': ' + kpRating + ' — ' + t.openExternal">{{ t.kp }}: {{ kpRating }}{{ isHighRating(kpRating) ? " ★" : "" }}</a>
          <a class="imdb" v-if="hasImdb" :href="imdbHref" target="_blank" rel="noopener noreferrer" :aria-label="t.imdb + ': ' + imdbRating + ' — ' + t.openExternal">{{ t.imdb }}: {{ imdbRating }}{{ isHighRating(imdbRating) ? " ★" : "" }}</a>
        </div>
        <div class="share-row" role="group" :aria-label="t.share">
          <a v-for="n in shareNets" :key="n.key" class="share-btn" :data-net="n.key" :href="n.href"
             target="_blank" rel="noopener noreferrer" :title="n.label" :aria-label="n.label">
            <svg class="share-ico" aria-hidden="true" viewBox="0 0 24 24"><use :href="'../../static/share.svg#icon-' + n.key"></use></svg>
          </a>
          <button v-if="nativeShare" type="button" class="share-btn share-native" data-net="native"
            :aria-label="t.shareNative" :title="t.shareNative" @click="doNativeShare">
            <svg class="share-ico" aria-hidden="true" viewBox="0 0 24 24"><use href="../../static/share.svg#icon-native"></use></svg>
          </button>
        </div>
        <span class="visually-hidden" role="status">{{ shareStatus }}</span>
      </div>
    </article>

    <section class="related" :aria-label="t.relatedH">
      <h2>{{ t.relatedH }}</h2>
      <ul v-if="related.length">
        <li v-for="r in related" :key="itemSlug(r)">
          <a class="rc" :href="'../' + itemSlug(r) + '/'">
            <img v-if="relatedPoster(r)" class="rc-poster" :src="relatedPoster(r)" :srcset="relatedPosterSrcset(r)" sizes="64px" alt="" width="64" height="96" loading="lazy" decoding="async">
            <span class="rc-content">
              <span class="rc-head">
                <span class="fav-icon" v-if="r.fav" :title="t.recommend"><svg class="fav-icon-svg" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 8.8c0 5.3-8.8 10.2-8.8 10.2S3.2 14.1 3.2 8.8A4.4 4.4 0 0 1 12 7.1a4.4 4.4 0 0 1 8.8 1.7Z" fill="currentColor"/></svg></span>
                <span class="rc-title">{{ relatedTitle(r) }}</span>
              </span>
              <span class="rc-alt" v-if="relatedAlt(r)">{{ relatedAlt(r) }}</span>
              <span class="rc-info">{{ relatedInfo(r) }}</span>
              <span class="rc-meta">
                <span class="rc-rating kp" v-if="hasRating(r.kpRating)">{{ t.kpShort }} {{ formatRating(r.kpRating) }}</span>
                <span class="rc-rating imdb" v-if="r.imdbId && hasRating(r.imdbRating)">{{ t.imdb }} {{ formatRating(r.imdbRating) }}</span>
              </span>
            </span>
          </a>
        </li>
      </ul>
      <p class="empty" v-else>{{ t.empty }}</p>
    </section>
    <p class="back-catalog"><a href="../../">← {{ t.backToCatalog }}</a></p>
  </main>

  <footer>
    <div class="footer-line">
      <span>{{ t.codedWith }}</span><svg class="heart" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 8.8c0 5.3-8.8 10.2-8.8 10.2S3.2 14.1 3.2 8.8A4.4 4.4 0 0 1 12 7.1a4.4 4.4 0 0 1 8.8 1.7Z" fill="currentColor"/></svg><a href="https://t.me/wh_lab" target="_blank" rel="noopener noreferrer">Exited3n</a>
    </div>
    <div class="footer-line">
      <a class="footer-privacy" href="../../privacy.html">{{ t.privacy }}</a>
    </div>
  </footer>
  <button class="scroll-top" :aria-label="t.scrollTop" @click="scrollToTop">↑</button>
`;const app=createApp({setup(){const pageData=window.FILM_PAGE||null;const item=(pageData&&pageData.item)||null;const urlParams=new URLSearchParams(location.search);const lang=ref(langFrom(urlParams,safeRead));const colorScheme=window.matchMedia("(prefers-color-scheme: light)");const theme=ref(themeFrom(urlParams,safeRead));let cleanupColorScheme=null;watch(theme,(value)=>toggleThemeClass(value),{immediate:true});onMounted(()=>{const onColorScheme=(e)=>{if(!safeRead("it-movies-theme")){theme.value=e.matches?"light":"dark";}};colorScheme.addEventListener("change",onColorScheme);cleanupColorScheme=()=>colorScheme.removeEventListener("change",onColorScheme);});onUnmounted(()=>{if(cleanupColorScheme)cleanupColorScheme();});function setLang(next){lang.value=next;}function setTheme(next){theme.value=next;safeWrite("it-movies-theme",next);}const t=computed(()=>I18N[lang.value]);const title=computed(()=>item?(lang.value==="ru"?item.titleRu:item.titleEn):"");const yearSuffix=item&&item.year?` (${item.year})`:"";const altTitle=computed(()=>{if(!item)return"";const primary=lang.value==="ru"?item.titleRu:item.titleEn;const other=lang.value==="ru"?item.titleEn:item.titleRu;return other&&other!==primary?other:"";});const desc=computed(()=>item?item.desc[lang.value==="ru"?"ru":"en"]:I18N[lang.value].fatalError);const typeLabel=computed(()=>item?t.value.typeLabels[item.type]||item.type:"");const genreLabel=computed(()=>item?item.genres.map((g)=>t.value.genres[g]||g).join(" / "):"");const year=computed(()=>(item?item.year:""));const posterSrc=computed(()=>item&&item.poster?"../../"+item.poster.replace(/^\//,""):"");const posterW=computed(()=>(pageData&&pageData.posterW)||null);const posterH=computed(()=>(pageData&&pageData.posterH)||null);const posterSrcset=computed(()=>{if(!posterSrc.value||!posterW.value)return null;const v400=posterSrc.value.replace(/\.webp$/,"_400.webp");return`${v400} 400w, ${posterSrc.value} ${posterW.value}w`;});const kpHref=computed(()=>(item?kpUrl(item):""));const imdbHref=computed(()=>(item&&item.imdbId?imdbUrl(item):""));const hasImdb=computed(()=>!!(item&&item.imdbId));const kpRating=computed(()=>item?formatRating(item.kpRating,"—"):"—");const imdbRating=computed(()=>item?formatRating(item.imdbRating,"—"):"—");const relatedPool=(pageData&&pageData.relatedPool)||[];const related=relatedPool.length>=6?pickRandom(relatedPool,6):(pageData&&pageData.related)||[];const SHARE_NETS={telegram:{label:"Telegram",href:(url,title)=>`https://t.me/share/url?url=${encodeURIComponent(url)}&text=${title}`},whatsapp:{label:"WhatsApp",href:(url,title)=>`https://wa.me/?text=${title}%0A%0A${encodeURIComponent(url)}`},vk:{label:"VK",href:(url,title)=>`https://vk.com/share.php?url=${encodeURIComponent(url)}&title=${title}`},x:{label:"X",href:(url,title)=>`https://x.com/intent/post?url=${encodeURIComponent(url)}&text=${title}`},linkedin:{label:"LinkedIn",href:(url)=>`https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`},reddit:{label:"Reddit",href:(url,title)=>`https://www.reddit.com/submit?url=${encodeURIComponent(url)}&title=${title}`},};const SHARE_ORDER=["telegram","whatsapp","vk","x","linkedin","reddit"];function shareUrl(){const canon=typeof document!=="undefined"&&document.querySelector?document.querySelector('link[rel="canonical"]'):null;return canon&&canon.href?canon.href:location.href;}const shareNets=computed(()=>{const url=shareUrl();const shareTitle=encodeURIComponent(title.value);return SHARE_ORDER.map((key)=>({key,label:SHARE_NETS[key].label,href:SHARE_NETS[key].href(url,shareTitle),}));});const nativeShare=typeof navigator!=="undefined"&&typeof navigator.share==="function";const shareStatus=ref("");function doNativeShare(){if(typeof navigator==="undefined"||typeof navigator.share!=="function")return;navigator.share({title:document.title,text:title.value,url:shareUrl(),}).catch((err)=>{if(err&&err.name==="AbortError")return;shareStatus.value=t.value.shareFailed;});}watch(lang,(value)=>{currentLang=value;safeWrite("it-movies-lang",value);document.documentElement.lang=value;document.title=`${title.value}${yearSuffix} — ${I18N[value].title}`;const metaDesc=document.querySelector('meta[name="description"]');if(metaDesc&&item&&item.descSeo)metaDesc.setAttribute("content",item.descSeo[value]);},{immediate:true});function relatedTitle(r){return lang.value==="ru"?r.titleRu:r.titleEn;}function relatedAlt(r){const primary=lang.value==="ru"?r.titleRu:r.titleEn;const other=lang.value==="ru"?r.titleEn:r.titleRu;return other&&other!==primary?other:"";}function relatedInfo(r){const tt=t.value;const parts=[];if(r.genres&&r.genres.length){parts.push(r.genres.map((g)=>tt.genres[g]||g).join(" / "));}if(r.year)parts.push(String(r.year));return parts.join(" · ");}function relatedPoster(r){return r.poster?"../../"+r.poster.replace(/^\//,""):"";}function relatedPosterSrcset(r){if(!r.poster)return null;const src=relatedPoster(r);return`${src.replace(/\.webp$/, "_400.webp")} 400w, ${src} 800w`;}return{lang,theme,t,title,altTitle,desc,typeLabel,genreLabel,year,posterSrc,posterW,posterH,posterSrcset,kpHref,imdbHref,hasImdb,kpRating,imdbRating,related,itemSlug,relatedTitle,relatedAlt,relatedInfo,relatedPoster,relatedPosterSrcset,formatRating,hasRating,isHighRating,shareNets,nativeShare,shareStatus,doNativeShare,setLang,setTheme,scrollToTop,};},template:FILM_TEMPLATE,});installErrorHandler(app,()=>currentLang,()=>I18N);app.mount("#app");